    visit0 = {sv: V for V, (visits, _) in packed.items() for sv in visits}
    hit = visit0.get(pfsConfig.visit)
    if hit is None:
        return
    rows = np.frombuffer(
        zlib.decompress(base64.b64decode(packed[hit][1])),
        dtype=[('fiberId', '<i4'), ('x', '<f8'), ('y', '<f8'),
               ('status', '<i4')],
    )
    # a subset (e.g. one spectrograph) carries only some of these fibres
    index = {int(fiberId): i
             for i, fiberId in enumerate(pfsConfig.fiberId)}
    for fiberId, x, y, status in rows:
        i = index.get(int(fiberId))
        if i is None:
            continue
        pfsConfig.pfiCenter[i] = (x, y)
        pfsConfig.fiberStatus[i] = int(status)
